add retries with backoff to our HTTP client. Right now one timeout from the payments API fails the whole nightly sync, and someone has to re-run it by hand. Tests run with `pytest -q` and lint with `ruff check .`. Work on the branch `http-retries`. I'll review the plan before anyone starts on it.

```python
# app/http_client.py
import requests

class HttpClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path, **params):
        r = requests.get(self.base_url + path, params=params, timeout=self.timeout)
        r.raise_for_status()
        return r.json()

    def post(self, path, payload):
        r = requests.post(self.base_url + path, json=payload, timeout=self.timeout)
        r.raise_for_status()
        return r.json()

# jobs/nightly_sync.py
from app.http_client import HttpClient

client = HttpClient("https://payments.internal", timeout=5)

def run():
    page = 1
    while rows := client.get("/settlements", page=page):
        save(rows)
        page += 1

